// The pipeline for each reader is: writer -> gzip (optional) -> encryption (optional) -> pipe.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		var w io.Writer = pw
		var closers []io.Closer

		if encryptor != nil {
			ew := encryptor.EncryptWriter(w)
			w = ew
			closers = append(closers, ew)
		}

		if compress {
			gw := gzip.NewWriter(w)
			w = gw
			closers = append(closers, gw)
		}

